-- CORE SYSTEM Financial/Inventory cumulative reconciliation after production migration 20260904144247.
-- Replays the post-44247 final state without destructive data changes.
begin;
insert into public.permissions(permission_key,permission_name,description,resource,action) values
('invoices:refund','Refund invoices','Create auditable invoice refunds without deleting original payments','invoices','refund'),
('purchasing:return','Return received purchasing stock','Return received stock against a purchase receipt','purchasing','return') on conflict(permission_key) do nothing;
insert into public.role_permissions(role_id,permission_id) select r.id,p.id from public.roles r cross join public.permissions p where r.role_key in ('clinic_admin','accounting') and r.tenant_id is null and p.permission_key in ('invoices:refund','purchasing:return') and not exists(select 1 from public.role_permissions rp where rp.role_id=r.id and rp.permission_id=p.id and rp.deleted_at is null);

create table if not exists public.invoice_refunds(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,invoice_id uuid not null,payment_id uuid,amount_subunits integer not null,refund_method text not null,reference text,reason text not null,refunded_by uuid not null,refunded_at timestamptz not null default now(),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz,constraint invoice_refunds_amount_positive check(amount_subunits>0),constraint invoice_refunds_method_check check(refund_method in ('cash','card','bank_transfer','online','other')));
alter table public.invoice_refunds enable row level security;
create unique index if not exists uq_invoice_refunds_tenant_id_id on public.invoice_refunds(tenant_id,id);
create index if not exists idx_invoice_refunds_invoice on public.invoice_refunds(tenant_id,invoice_id,refunded_at desc);
drop policy if exists invoice_refunds_select on public.invoice_refunds; drop policy if exists invoice_refunds_insert on public.invoice_refunds;
create policy invoice_refunds_select on public.invoice_refunds for select to authenticated using(tenant_id=public.get_current_tenant_id() and public.has_tenant_permission(tenant_id,'invoices:read'));
create policy invoice_refunds_insert on public.invoice_refunds for insert to authenticated with check(tenant_id=public.get_current_tenant_id() and public.has_tenant_permission(tenant_id,'invoices:refund'));
revoke all on public.invoice_refunds from anon; grant select,insert on public.invoice_refunds to authenticated;

create table if not exists public.inventory_lots(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,inventory_item_id uuid not null,lot_number text not null,expiry_date date,quantity_on_hand integer not null default 0,unit_cost_subunits integer,status text not null default 'active',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz,constraint inventory_lots_qty_nonnegative check(quantity_on_hand>=0),constraint inventory_lots_status_check check(status in ('active','expired','quarantined','depleted')));
alter table public.inventory_lots enable row level security;
create unique index if not exists uq_inventory_lots_tenant_id_id on public.inventory_lots(tenant_id,id);
create unique index if not exists uq_inventory_lots_tenant_item_lot on public.inventory_lots(tenant_id,inventory_item_id,lot_number) where deleted_at is null;
create index if not exists idx_inventory_lots_expiry on public.inventory_lots(tenant_id,expiry_date) where deleted_at is null;
drop policy if exists inventory_lots_select on public.inventory_lots; drop policy if exists inventory_lots_write on public.inventory_lots;
create policy inventory_lots_select on public.inventory_lots for select to authenticated using(tenant_id=public.get_current_tenant_id() and public.has_tenant_permission(tenant_id,'inventory:read'));
create policy inventory_lots_write on public.inventory_lots for all to authenticated using(tenant_id=public.get_current_tenant_id() and public.has_tenant_permission(tenant_id,'inventory:update')) with check(tenant_id=public.get_current_tenant_id() and public.has_tenant_permission(tenant_id,'inventory:update'));
revoke all on public.inventory_lots from anon; grant select,insert,update,delete on public.inventory_lots to authenticated;

alter table public.purchase_receipt_items add column if not exists quantity_returned integer not null default 0;
alter table public.purchase_receipt_items add constraint purchase_receipt_items_return_nonnegative check(quantity_returned>=0 and quantity_returned<=quantity_received) not valid;
alter table public.purchase_receipt_items validate constraint purchase_receipt_items_return_nonnegative;

create or replace function public.guard_invoice_mutation() returns trigger language plpgsql set search_path='public' as $function$
begin
 if old.invoice_status in ('issued','paid','partial','refunded') then
  if new.tenant_id is distinct from old.tenant_id or new.patient_id is distinct from old.patient_id or new.session_id is distinct from old.session_id or new.invoice_date is distinct from old.invoice_date or new.invoice_number is distinct from old.invoice_number or new.subtotal_subunits is distinct from old.subtotal_subunits or new.discount_subunits is distinct from old.discount_subunits or new.discount_reason is distinct from old.discount_reason or new.discount_approved_by is distinct from old.discount_approved_by or new.tax_subunits is distinct from old.tax_subunits or new.total_subunits is distinct from old.total_subunits or new.payment_terms is distinct from old.payment_terms or new.notes is distinct from old.notes or new.deleted_at is distinct from old.deleted_at then raise exception 'Issued/paid invoice financial facts are immutable'; end if;
  if new.amount_paid_subunits is distinct from old.amount_paid_subunits and coalesce(current_setting('core.invoice_refund_mutation',true),'')<>'1' and coalesce(current_setting('core.invoice_payment_mutation',true),'')<>'1' then raise exception 'Collected amount is controlled by canonical payment/refund operations'; end if;
 end if;
 if old.invoice_status in ('paid','refunded') and new.invoice_status not in ('paid','refunded','partial') then raise exception 'Paid/refunded invoice cannot move backward'; end if;
 return new;
end;$function$;

create or replace function public.create_manual_invoice(p_tenant_id uuid,p_patient_id uuid,p_session_id uuid default null,p_invoice_date date default current_date,p_payment_terms text default 'cash',p_notes text default null,p_created_by uuid default null,p_items jsonb default '[]'::jsonb) returns jsonb language plpgsql set search_path='public' as $function$
declare v_invoice_id uuid; v_row jsonb; v_procedure record; v_desc text; v_qty integer; v_price integer; v_disc integer; v_disc_pct numeric; v_eff_disc integer; v_tax_rate numeric; v_tax_included boolean; v_after integer; v_tax integer; v_sub integer:=0; v_total integer:=0; v_tax_total integer:=0; v_discount integer:=0; v_sort integer:=0; v_actor uuid;
begin
 if public.get_current_tenant_id() is distinct from p_tenant_id or not public.has_tenant_permission(p_tenant_id,'invoices:create') then return jsonb_build_object('success',false,'error','Permission denied'); end if;
 v_actor:=coalesce(p_created_by,auth.uid()); if v_actor is not null and not exists(select 1 from public.clinic_users where id=v_actor and tenant_id=p_tenant_id and is_active and deleted_at is null) then return jsonb_build_object('success',false,'error','Creator does not belong to tenant'); end if;
 if not exists(select 1 from public.clinic_patients where id=p_patient_id and tenant_id=p_tenant_id and deleted_at is null) then return jsonb_build_object('success',false,'error','Patient not found'); end if;
 if p_session_id is not null and not exists(select 1 from public.clinic_visit_sessions where id=p_session_id and tenant_id=p_tenant_id and patient_id=p_patient_id) then return jsonb_build_object('success',false,'error','Session not found'); end if;
 if jsonb_typeof(p_items)<>'array' or jsonb_array_length(p_items)=0 then return jsonb_build_object('success',false,'error','Invoice must have at least one item'); end if;
 insert into public.clinic_invoices(tenant_id,patient_id,session_id,invoice_date,invoice_status,payment_terms,notes,subtotal_subunits,total_subunits,tax_subunits,discount_subunits,amount_paid_subunits) values(p_tenant_id,p_patient_id,p_session_id,p_invoice_date,'draft',p_payment_terms,p_notes,0,0,0,0,0) returning id into v_invoice_id;
 for v_row in select value from jsonb_array_elements(p_items) loop
  v_desc:=trim(coalesce(v_row->>'description','')); v_qty:=(v_row->>'quantity')::integer; v_price:=(v_row->>'unit_price_subunits')::integer; v_disc:=coalesce((v_row->>'discount_amount_subunits')::integer,0); v_disc_pct:=nullif(v_row->>'discount_percent','')::numeric;
  if v_desc='' or v_qty is null or v_qty<=0 or v_price is null or v_price<0 or v_disc<0 then raise exception 'Invalid invoice item'; end if;
  v_tax_rate:=coalesce(nullif(v_row->>'tax_rate_percent','')::numeric,0); v_tax_included:=false;
  if nullif(v_row->>'procedure_id','') is not null then select tax_rate_percent,tax_included into v_procedure from public.clinic_procedures where id=(v_row->>'procedure_id')::uuid and tenant_id=p_tenant_id and is_active=true; if not found then raise exception 'Procedure not found'; end if; v_tax_rate:=coalesce(nullif(v_row->>'tax_rate_percent','')::numeric,v_procedure.tax_rate_percent); v_tax_included=v_procedure.tax_included; end if;
  if v_disc_pct is not null then if v_disc_pct<0 or v_disc_pct>100 then raise exception 'Invalid discount percent'; end if; v_eff_disc:=round((v_qty*v_price)*(v_disc_pct/100.0)); else v_eff_disc:=v_disc; end if;
  if v_eff_disc>(v_qty*v_price) then raise exception 'Discount exceeds item amount'; end if; if v_eff_disc>0 and not public.has_tenant_permission(p_tenant_id,'invoices:discount') then raise exception 'Discount permission required'; end if;
  v_after:=(v_qty*v_price)-v_eff_disc; if v_tax_included then v_tax:=round(v_after*(v_tax_rate/(100+v_tax_rate))); else v_tax:=round(v_after*(v_tax_rate/100)); end if;
  insert into public.invoice_items(tenant_id,invoice_id,procedure_id,item_description,item_description_ar,quantity,unit_price_subunits,discount_subunits,tax_rate_percent,tax_subunits,sort_order) values(p_tenant_id,v_invoice_id,nullif(v_row->>'procedure_id','')::uuid,v_desc,nullif(v_row->>'description_ar',''),v_qty,v_price,v_eff_disc,v_tax_rate,v_tax,v_sort);
  v_sub:=v_sub+(v_qty*v_price); v_discount:=v_discount+v_eff_disc; v_tax_total:=v_tax_total+v_tax; v_total:=v_total+v_after+v_tax; v_sort:=v_sort+1;
 end loop;
 update public.clinic_invoices set subtotal_subunits=v_sub,discount_subunits=v_discount,tax_subunits=v_tax_total,total_subunits=v_total,discount_approved_by=case when v_discount>0 then v_actor else null end,updated_at=now() where id=v_invoice_id and tenant_id=p_tenant_id;
 return jsonb_build_object('success',true,'invoice_id',v_invoice_id);
exception when others then return jsonb_build_object('success',false,'error',sqlerrm); end;$function$;

create or replace function public.record_invoice_payment(p_tenant_id uuid,p_invoice_id uuid,p_amount_subunits integer,p_payment_method text,p_payment_reference text default null,p_notes text default null,p_collected_by uuid default null) returns jsonb language plpgsql set search_path='public' as $function$
declare v_invoice record; v_payment_id uuid; v_paid integer; v_status text; v_actor uuid;
begin if public.get_current_tenant_id() is distinct from p_tenant_id or not public.has_tenant_permission(p_tenant_id,'invoices:payment') then return jsonb_build_object('success',false,'error','Permission denied'); end if; if p_amount_subunits<=0 then return jsonb_build_object('success',false,'error','Payment amount must be positive'); end if; v_actor:=coalesce(p_collected_by,auth.uid()); if v_actor is null or not exists(select 1 from public.clinic_users where id=v_actor and tenant_id=p_tenant_id and is_active and deleted_at is null) then return jsonb_build_object('success',false,'error','Collector does not belong to tenant'); end if; select * into v_invoice from public.clinic_invoices where id=p_invoice_id and tenant_id=p_tenant_id for update; if not found or v_invoice.invoice_status in ('cancelled','refunded','draft') then return jsonb_build_object('success',false,'error','Invoice is not payable'); end if; if p_amount_subunits>greatest(v_invoice.total_subunits-v_invoice.amount_paid_subunits,0) then return jsonb_build_object('success',false,'error','Payment exceeds remaining balance'); end if; insert into public.invoice_payments(tenant_id,invoice_id,amount_subunits,payment_method,payment_reference,notes,collected_by) values(p_tenant_id,p_invoice_id,p_amount_subunits,p_payment_method,p_payment_reference,p_notes,v_actor) returning id into v_payment_id; v_paid:=v_invoice.amount_paid_subunits+p_amount_subunits; v_status:=case when v_paid>=v_invoice.total_subunits then 'paid' else 'partial' end; perform set_config('core.invoice_payment_mutation','1',true); update public.clinic_invoices set amount_paid_subunits=v_paid,invoice_status=v_status,collected_by=v_actor,payment_method=p_payment_method,updated_at=now() where id=p_invoice_id and tenant_id=p_tenant_id; return jsonb_build_object('success',true,'payment_id',v_payment_id,'status',v_status,'amount_paid',v_paid); exception when others then return jsonb_build_object('success',false,'error',sqlerrm); end;$function$;

create or replace function public.record_invoice_payment_with_installment(p_tenant_id uuid,p_invoice_id uuid,p_amount_subunits integer,p_payment_method text,p_payment_reference text default null,p_notes text default null,p_collected_by uuid default null,p_installment_id uuid default null) returns jsonb language plpgsql set search_path='public' as $function$
declare v_invoice record; v_installment record; v_payment_id uuid; v_plan_id uuid; v_paid integer; v_status text; v_actor uuid;
begin if public.get_current_tenant_id() is distinct from p_tenant_id or not public.has_tenant_permission(p_tenant_id,'invoices:payment') then return jsonb_build_object('success',false,'error','Permission denied'); end if; if p_amount_subunits<=0 then return jsonb_build_object('success',false,'error','Payment amount must be positive'); end if; v_actor:=coalesce(p_collected_by,auth.uid()); if v_actor is null or not exists(select 1 from public.clinic_users where id=v_actor and tenant_id=p_tenant_id and is_active and deleted_at is null) then return jsonb_build_object('success',false,'error','Collector does not belong to tenant'); end if; select * into v_invoice from public.clinic_invoices where id=p_invoice_id and tenant_id=p_tenant_id for update; if not found or v_invoice.invoice_status in ('cancelled','refunded','draft') then return jsonb_build_object('success',false,'error','Invoice is not payable'); end if; if p_amount_subunits>greatest(v_invoice.total_subunits-v_invoice.amount_paid_subunits,0) then return jsonb_build_object('success',false,'error','Payment exceeds remaining balance'); end if; if p_installment_id is not null then select * into v_installment from public.financial_installments where id=p_installment_id and tenant_id=p_tenant_id and deleted_at is null for update; if not found or (v_installment.invoice_id is not null and v_installment.invoice_id<>p_invoice_id) then return jsonb_build_object('success',false,'error','Installment is invalid for this invoice'); end if; if p_amount_subunits>greatest(v_installment.amount_subunits-v_installment.amount_paid_subunits,0) then return jsonb_build_object('success',false,'error','Payment exceeds installment balance'); end if; v_plan_id:=v_installment.financial_plan_id; end if; insert into public.invoice_payments(tenant_id,invoice_id,financial_plan_id,installment_id,amount_subunits,payment_method,payment_reference,notes,collected_by) values(p_tenant_id,p_invoice_id,v_plan_id,p_installment_id,p_amount_subunits,p_payment_method,p_payment_reference,p_notes,v_actor) returning id into v_payment_id; v_paid:=v_invoice.amount_paid_subunits+p_amount_subunits; v_status:=case when v_paid>=v_invoice.total_subunits then 'paid' else 'partial' end; perform set_config('core.invoice_payment_mutation','1',true); update public.clinic_invoices set amount_paid_subunits=v_paid,invoice_status=v_status,collected_by=v_actor,payment_method=p_payment_method,updated_at=now() where id=p_invoice_id and tenant_id=p_tenant_id; if p_installment_id is not null then update public.financial_installments set invoice_id=coalesce(invoice_id,p_invoice_id),amount_paid_subunits=amount_paid_subunits+p_amount_subunits,status=case when amount_paid_subunits+p_amount_subunits>=amount_subunits then 'paid' else 'partial' end,updated_at=now() where id=p_installment_id and tenant_id=p_tenant_id; end if; return jsonb_build_object('success',true,'payment_id',v_payment_id,'financial_plan_id',v_plan_id,'installment_id',p_installment_id,'status',v_status,'amount_paid',v_paid); exception when others then return jsonb_build_object('success',false,'error',sqlerrm); end;$function$;

create or replace function public.refund_invoice_payment(p_tenant_id uuid,p_invoice_id uuid,p_amount_subunits integer,p_refund_method text,p_reason text,p_refunded_by uuid,p_payment_id uuid default null,p_reference text default null) returns jsonb language plpgsql security definer set search_path='public' as $function$
declare v_invoice record; v_refunded integer; v_refundable integer; v_id uuid; v_actor uuid; v_new integer;
begin if public.get_current_tenant_id() is distinct from p_tenant_id or not public.has_tenant_permission(p_tenant_id,'invoices:refund') then return jsonb_build_object('success',false,'error','Permission denied'); end if; v_actor:=coalesce(p_refunded_by,auth.uid()); if v_actor is null or not exists(select 1 from public.clinic_users where id=v_actor and tenant_id=p_tenant_id and is_active and deleted_at is null) then return jsonb_build_object('success',false,'error','Refund actor does not belong to tenant'); end if; if p_amount_subunits<=0 or trim(coalesce(p_reason,''))='' then return jsonb_build_object('success',false,'error','Refund amount and reason are required'); end if; select * into v_invoice from public.clinic_invoices where id=p_invoice_id and tenant_id=p_tenant_id for update; if not found or v_invoice.invoice_status not in ('issued','partial','paid','refunded') then return jsonb_build_object('success',false,'error','Invoice is not refundable'); end if; select coalesce(sum(amount_subunits),0) into v_refunded from public.invoice_refunds where invoice_id=p_invoice_id and tenant_id=p_tenant_id and deleted_at is null; v_refundable:=greatest(v_invoice.amount_paid_subunits-v_refunded,0); if p_amount_subunits>v_refundable then return jsonb_build_object('success',false,'error','Refund exceeds refundable amount'); end if; if p_payment_id is not null and not exists(select 1 from public.invoice_payments where id=p_payment_id and invoice_id=p_invoice_id and tenant_id=p_tenant_id) then return jsonb_build_object('success',false,'error','Payment not found for invoice'); end if; insert into public.invoice_refunds(tenant_id,invoice_id,payment_id,amount_subunits,refund_method,reference,reason,refunded_by) values(p_tenant_id,p_invoice_id,p_payment_id,p_amount_subunits,p_refund_method,p_reference,trim(p_reason),v_actor) returning id into v_id; v_new:=greatest(v_invoice.amount_paid_subunits-p_amount_subunits,0); perform set_config('core.invoice_refund_mutation','1',true); update public.clinic_invoices set amount_paid_subunits=v_new,invoice_status=case when v_new=0 then 'refunded' else 'partial' end,updated_at=now() where id=p_invoice_id and tenant_id=p_tenant_id; return jsonb_build_object('success',true,'refund_id',v_id,'amount_refunded',p_amount_subunits,'net_collected',v_new); exception when others then return jsonb_build_object('success',false,'error',sqlerrm); end;$function$;
revoke all on function public.refund_invoice_payment(uuid,uuid,integer,text,text,uuid,uuid,text) from public,anon; grant execute on function public.refund_invoice_payment(uuid,uuid,integer,text,text,uuid,uuid,text) to authenticated;

create or replace function public.get_financial_resource_summary(p_tenant_id uuid,p_from_date date default null,p_to_date date default null) returns jsonb language plpgsql set search_path='public' as $function$
declare v_from date:=coalesce(p_from_date,date_trunc('month',current_date)::date); v_to date:=coalesce(p_to_date,current_date); begin if public.get_current_tenant_id() is distinct from p_tenant_id or not public.has_tenant_permission(p_tenant_id,'reports:read') then raise exception 'Permission denied'; end if; return jsonb_build_object('period',jsonb_build_object('from',v_from,'to',v_to),'revenue_subunits',coalesce((select sum(total_subunits) from public.clinic_invoices where tenant_id=p_tenant_id and invoice_status<>'cancelled' and invoice_date between v_from and v_to and deleted_at is null),0),'collections_subunits',coalesce((select sum(amount_subunits) from public.invoice_payments where tenant_id=p_tenant_id and payment_date::date between v_from and v_to),0),'refunds_subunits',coalesce((select sum(amount_subunits) from public.invoice_refunds where tenant_id=p_tenant_id and refunded_at::date between v_from and v_to and deleted_at is null),0),'outstanding_subunits',coalesce((select sum(greatest(total_subunits-amount_paid_subunits,0)) from public.clinic_invoices where tenant_id=p_tenant_id and invoice_status in ('issued','partial') and deleted_at is null),0),'inventory_value_subunits',coalesce((select sum(current_stock*coalesce(valuation_cost_subunits,purchase_cost_subunits,0)) from public.inventory_items where tenant_id=p_tenant_id and deleted_at is null),0),'supplier_payables_subunits',coalesce((select sum(greatest(amount_subunits-amount_paid_subunits,0)) from public.supplier_obligations where tenant_id=p_tenant_id and status<>'cancelled'),0),'operating_expenses_subunits',coalesce((select sum(amount_subunits) from public.operating_expenses where tenant_id=p_tenant_id and expense_date between v_from and v_to),0),'invoice_count',(select count(*) from public.clinic_invoices where tenant_id=p_tenant_id and invoice_date between v_from and v_to and deleted_at is null),'payment_count',(select count(*) from public.invoice_payments where tenant_id=p_tenant_id and payment_date::date between v_from and v_to),'inventory_item_count',(select count(*) from public.inventory_items where tenant_id=p_tenant_id and deleted_at is null),'legacy_untraceable_inventory_movements',(select count(*) from public.inventory_ledger where tenant_id=p_tenant_id and source_type='legacy_untraceable')); end;$function$;
revoke all on function public.get_financial_resource_summary(uuid,date,date) from public,anon; grant execute on function public.get_financial_resource_summary(uuid,date,date) to authenticated;

create or replace function public.return_unused_inventory(p_tenant_id uuid,p_item_id uuid,p_quantity integer,p_visit_id uuid,p_treatment_plan_item_id uuid,p_returned_by uuid,p_reason text) returns jsonb language plpgsql security definer set search_path='public' as $function$
declare v_new integer; v_proc uuid; begin if public.get_current_tenant_id() is distinct from p_tenant_id or not public.has_tenant_permission(p_tenant_id,'inventory:adjust') then return jsonb_build_object('success',false,'error','Permission denied'); end if; if p_quantity<=0 or not exists(select 1 from public.clinic_users where id=p_returned_by and tenant_id=p_tenant_id and is_active and deleted_at is null) then return jsonb_build_object('success',false,'error','Invalid return'); end if; if not exists(select 1 from public.clinic_visit_sessions where id=p_visit_id and tenant_id=p_tenant_id) then return jsonb_build_object('success',false,'error','Visit not found'); end if; select mae.procedure_id into v_proc from public.clinic_visit_sessions cvs left join public.master_agenda_events mae on mae.id=cvs.agenda_event_id where cvs.id=p_visit_id and cvs.tenant_id=p_tenant_id; v_new:=public.adjust_inventory_stock(p_item_id,p_tenant_id,p_quantity,'unused_return','unused_return',p_visit_id,v_proc,p_visit_id,p_treatment_plan_item_id,p_returned_by,p_reason); return jsonb_build_object('success',true,'new_stock',v_new); exception when others then return jsonb_build_object('success',false,'error',sqlerrm); end;$function$;
revoke all on function public.return_unused_inventory(uuid,uuid,integer,uuid,uuid,uuid,text) from public,anon; grant execute on function public.return_unused_inventory(uuid,uuid,integer,uuid,uuid,uuid,text) to authenticated;

create or replace function public.return_purchase_receipt_item(p_tenant_id uuid,p_receipt_item_id uuid,p_quantity integer,p_returned_by uuid,p_reason text) returns jsonb language plpgsql security definer set search_path='public' as $function$
declare v record; v_new integer; v_reduction integer; begin if public.get_current_tenant_id() is distinct from p_tenant_id or not public.has_tenant_permission(p_tenant_id,'purchasing:return') then return jsonb_build_object('success',false,'error','Permission denied'); end if; if p_quantity<=0 or not exists(select 1 from public.clinic_users where id=p_returned_by and tenant_id=p_tenant_id and is_active and deleted_at is null) then return jsonb_build_object('success',false,'error','Invalid return'); end if; select pri.*,poi.unit_cost_subunits,poi.inventory_item_id,poi.id purchase_order_item_id,po.id purchase_order_id into v from public.purchase_receipt_items pri join public.purchase_order_items poi on poi.id=pri.purchase_order_item_id and poi.tenant_id=p_tenant_id join public.purchase_orders po on po.id=poi.purchase_order_id and po.tenant_id=p_tenant_id where pri.id=p_receipt_item_id and pri.tenant_id=p_tenant_id for update; if not found then return jsonb_build_object('success',false,'error','Receipt item not found'); end if; if p_quantity>(v.quantity_received-v.quantity_returned) then return jsonb_build_object('success',false,'error','Return exceeds remaining received quantity'); end if; v_new:=public.adjust_inventory_stock(v.inventory_item_id,p_tenant_id,-p_quantity,'purchase_return','purchase_return',p_receipt_item_id,null,null,null,p_returned_by,p_reason); update public.purchase_receipt_items set quantity_returned=quantity_returned+p_quantity where id=p_receipt_item_id and tenant_id=p_tenant_id; update public.purchase_order_items set quantity_received=greatest(quantity_received-p_quantity,0),updated_at=now() where id=v.purchase_order_item_id and tenant_id=p_tenant_id; v_reduction:=p_quantity*v.unit_cost_subunits; update public.supplier_obligations set amount_subunits=greatest(amount_subunits-v_reduction,amount_paid_subunits),updated_at=now() where purchase_order_id=v.purchase_order_id and tenant_id=p_tenant_id; return jsonb_build_object('success',true,'new_stock',v_new,'payable_reduction_subunits',v_reduction); exception when others then return jsonb_build_object('success',false,'error',sqlerrm); end;$function$;
revoke all on function public.return_purchase_receipt_item(uuid,uuid,integer,uuid,text) from public,anon; grant execute on function public.return_purchase_receipt_item(uuid,uuid,integer,uuid,text) to authenticated;

commit;
